// Shared helpers. tools/build.mjs copies this block into every Code node that says "//@include shared.js",
// because an n8n Code node cannot import local files.
const cfg = $('Config').first().json;

// Test clock: honoured only when Config.allowTestClock is true (tests and demos). Production ignores the TestNow field.
const clock = () => (cfg.allowTestClock === true && cfg.testNow ? new Date(cfg.testNow) : new Date());

// US numbers only. Returns +1XXXXXXXXXX or null. Area code and exchange must start with 2-9.
function toE164(raw) {
  let d = String(raw ?? '').replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('1')) d = d.slice(1);
  return /^[2-9]\d{2}[2-9]\d{6}$/.test(d) ? '+1' + d : null;
}

// Local weekday / hour / month in the business time zone.
function localParts(date, tz) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, weekday: 'short', hour: 'numeric', hourCycle: 'h23', month: 'numeric',
  }).formatToParts(date);
  const get = (t) => parts.find((p) => p.type === t)?.value;
  return { weekday: get('weekday'), hour: Number(get('hour')), month: Number(get('month')) };
}
// Reads the customer's text with plain rules (no AI): address, ZIP, problem type, urgency, language.
const hook = $('Customer Reply Webhook').first().json.body ?? {};
const now = clock();
const from = toE164(hook.From);
const to = toE164(hook.To);
const text = String(hook.Body ?? '').replace(/\s+/g, ' ').trim();
const base = { receivedAt: now.toISOString(), messageSid: hook.MessageSid ?? null };
if (!from || !to) {
  const bad = !from ? hook.From : hook.To;
  return [{ json: { ...base, route: 'invalid', reason: `${!from ? 'customer' : 'business'} number "${bad ?? ''}" is not a valid US number, message not processed` } }];
}

// lower case, accents removed: "calefacción" and "calefaccion" hit the same rule
const t = text.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

// Language: English unless two different Spanish words show up.
const esWords = new Set(t.match(/\b(hola|necesito|por favor|gracias|calle|avenida|vivo|estoy|tengo|tiene|hay|sin|funciona|fuga|agua|calefaccion|aire|acondicionado|puerta|garaje|casa|ayuda|urgente|huele|luz)\b/g) ?? []);
const language = esWords.size >= 2 ? 'es' : 'en';

// Street address: house number + street name + street word (St, Ave, Rd ...), optional unit.
const SUFFIX = 'street|st|avenue|ave|boulevard|blvd|road|rd|drive|dr|lane|ln|court|ct|way|place|pl|circle|cir|parkway|pkwy|trail|trl|terrace|ter|highway|hwy';
const NOT_A_STREET_NAME = new Set(['in', 'the', 'of', 'my', 'and', 'at', 'is', 'are', 'to', 'a', 'on', 'for', 'we', 'i']);
const streetRe = new RegExp(`\\b(\\d{1,6})\\s+((?:[A-Za-z0-9.'-]+\\s+){0,3}?[A-Za-z0-9.'-]+)\\s+(?:${SUFFIX})\\b\\.?(?:,?\\s+(?:apt|unit|suite|ste|#)\\.?\\s*[A-Za-z0-9-]+)?`, 'gi');
let address = null;
let span = null;
for (const m of text.matchAll(streetRe)) {
  if (m[2].toLowerCase().split(/\s+/).some((w) => NOT_A_STREET_NAME.has(w))) continue;
  address = m[0].replace(/[.,]+$/, '');
  span = [m.index, m.index + m[0].length];
  break;
}

// City, state, ZIP right after the street ("Dallas TX 75201"); otherwise the last 5-digit number outside the street.
let city = null;
let state = null;
let zip = null;
const csz = /,?\s*([A-Z][A-Za-z.' -]{1,24}?),?\s+([A-Z]{2})\b,?\s*(\d{5})(?:-\d{4})?/.exec(span ? text.slice(span[1]) : text);
if (csz) {
  city = csz[1].trim();
  state = csz[2];
  zip = csz[3];
} else {
  const zips = [...text.matchAll(/\b(\d{5})(?:-\d{4})?\b/g)].filter((m) => !(span && m.index >= span[0] && m.index < span[1]));
  if (zips.length) zip = zips[zips.length - 1][1];
}

// Problem type. A gas smell is an urgency flag, not a "leak" job, so those words are removed before the type rules run.
const GAS = "\\b(smell(s|ed|ing)? (of |like )?(natural )?gas|gas (smell|odor|leak|leaking)|(natural )?gas is leaking|rotten eggs?|huele a gas|olor a gas|fuga de gas)\\b";
const hasGas = new RegExp(GAS).test(t);
const tNoGas = t.replace(new RegExp(GAS, 'g'), ' ');
const TYPES = [
  ['no heat', /\bno (heat|heating|hot air)\b|\bnot (heating|blowing hot)|\bheat(er|ing)? (is |has |isn'?t |won'?t |stopped |went )?(out|off|not working|broken|down|dead|quit)\b|\bfurnace\b|\bboiler\b|(?<!water )\bheater\b|calefaccion|no calienta|\b(house|home) is (freezing|cold)\b/],
  ['no cool', /\bno (cool|cold air|cooling|ac|a\/c)\b|\b(ac|a\/c|air condition(er|ing)?)\b|\bnot (cooling|blowing cold)|\bwarm air\b|\bblowing warm\b|aire acondicionado|no enfria|sin aire|\b(house|home) is (hot|warm)\b/],
  ['garage door', /\bgarage\b|garaje|\bopener\b|\boverhead door\b/],
  ['electrical', /\belectric(al|ian)?\b|\boutlets?\b|\bbreakers?\b|\bcircuit\b|\bno power\b|\bpower (is |went )?out\b|\bwiring\b|\bfuse\b|\bsparks?\b|\bsparking\b|\bpanel\b|corto circuito|apagon|sin luz/],
  ['leak', /\bleak(s|ing|ed|y)?\b|\bdrip(s|ping)?\b|\bflood(ed|ing|s)?\b|\bburst\b|\bpipes?\b|\bfaucet\b|\bsink\b|\btoilet\b|\bdrain\b|\bclog(ged)?\b|\bsewer\b|\bwater heater\b|\bwater (is )?(everywhere|pouring|coming|on the floor)\b|fuga de agua|gotea|inundacion|tuberia|plomer/],
];
const matched = TYPES.filter(([, re]) => re.test(tNoGas)).map(([name]) => name);
const problemType = matched[0] ?? 'other';

// Urgency: gas smell, carbon monoxide, flooding, smoke or fire, and "no heat" in the winter months from Config.
const winterMonths = String(cfg.winterMonths).split(',').map((s) => Number(s.trim()));
const winter = winterMonths.includes(localParts(now, cfg.businessTimezone).month);
const urgencyReasons = [];
if (hasGas) urgencyReasons.push('gas smell');
if (/carbon monoxide|\bco (alarm|detector)\b|monoxido/.test(t)) urgencyReasons.push('carbon monoxide');
if (/\bflood(ed|ing|s)?\b|\bburst (pipe|pipes)\b|\bpipe (burst|broke|is broken)\b|\bwater (is )?(everywhere|pouring|gushing|rushing)\b|inundacion|se inundo|tuberia rota/.test(t)) urgencyReasons.push('flooding');
if (/\bsmoke\b|\bon fire\b|\bfire\b|\bsparks?\b|\bsparking\b|burning smell|smells? (like )?(burning|smoke)|\bhumo\b|chispas|huele a quemado/.test(t)) urgencyReasons.push('smoke, fire or sparks');
if (problemType === 'no heat' && winter) urgencyReasons.push('no heat in winter');

return [{ json: {
  ...base, route: 'ok', from, to, text: text.slice(0, 400), language,
  address, city, state, zip, problemType, alsoMentioned: matched.slice(1),
  urgent: urgencyReasons.length > 0, urgencyReasons, missing: address ? [] : ['address'],
} }];

// Remembers each customer for Config.dedupeHours. Decides: card (make a job card), ask_info (ask for the address),
// or duplicate (this customer already has a job card, so no second one).
const cfg = $('Config').first().json;
const msg = $input.first().json;
const store = $getWorkflowStaticData('global');
store.customers = store.customers ?? {};
store.seq = store.seq ?? 0;

const now = new Date(msg.receivedAt).getTime();
const windowMs = Number(cfg.dedupeHours) * 3600 * 1000;
for (const [num, rec] of Object.entries(store.customers)) {
  if (now - rec.firstAt >= windowMs) delete store.customers[num];
}
const prev = store.customers[msg.from];

// Fill the gaps from earlier messages inside the window; new information wins.
const messages = [...(prev?.messages ?? []), msg.text].slice(-5);
const merged = {
  address: msg.address ?? prev?.address ?? null,
  city: msg.city ?? prev?.city ?? null,
  state: msg.state ?? prev?.state ?? null,
  zip: msg.zip ?? prev?.zip ?? null,
  problemType: msg.problemType !== 'other' ? msg.problemType : (prev?.problemType ?? 'other'),
  language: msg.language === 'es' ? 'es' : (prev?.language ?? msg.language),
  urgencyReasons: [...new Set([...(prev?.urgencyReasons ?? []), ...msg.urgencyReasons])],
};
merged.urgent = merged.urgencyReasons.length > 0;

let route;
if (prev?.jobId && !(prev.addressMissing && merged.address)) route = 'duplicate';
else if (merged.address) route = 'card';
else if (merged.urgent || (prev?.asks ?? 0) >= 2) route = 'card'; // urgent, or asked twice already: a person takes over
else route = 'ask_info';

const isUpdate = route === 'card' && Boolean(prev?.jobId);
let jobId = prev?.jobId ?? null;
if (route === 'card' && !jobId) {
  store.seq += 1;
  const day = new Intl.DateTimeFormat('en-CA', { timeZone: cfg.businessTimezone }).format(new Date(msg.receivedAt)).replace(/-/g, '');
  jobId = `J-${day}-${String(store.seq).padStart(3, '0')}`;
}

const rec = {
  ...(prev ?? {}), ...merged, messages, jobId,
  firstAt: prev?.firstAt ?? now, lastAt: now, replies: (prev?.replies ?? 0) + 1,
  asks: (prev?.asks ?? 0) + (route === 'ask_info' ? 1 : 0),
  cardAt: route === 'card' ? now : prev?.cardAt,
  addressMissing: route === 'card' ? !merged.address : prev?.addressMissing,
};
store.customers[msg.from] = rec;

const out = { ...msg, ...merged, message: messages.join(' | '), route, isUpdate, jobId, addressMissing: !merged.address, asks: rec.asks, replies: rec.replies };
if (route === 'duplicate') out.reason = `${msg.from} already has job ${prev.jobId} (created ${new Date(prev.cardAt).toISOString()}), no second job card`;
return [{ json: out }];

// Builds the job card: the Slack message (Block Kit, with Assign and Call back buttons) and the row for the jobs sheet.
const m = $input.first().json;
const LABEL = { 'no heat': 'No heat', 'no cool': 'No cooling (A/C)', 'garage door': 'Garage door', electrical: 'Electrical', leak: 'Leak / plumbing', other: 'Other / not sure' };
const problem = LABEL[m.problemType] ?? 'Other / not sure';
const place = [m.address, m.city, [m.state, m.zip].filter(Boolean).join(' ')].filter(Boolean).join(', ');
const addressLine = m.address ? place : (m.zip ? `address missing (ZIP ${m.zip})` : 'address missing');
const tag = m.urgent ? '🚨 URGENT' : (m.isUpdate ? '🔄 UPDATE' : '🆕 New job');
const reasons = m.urgencyReasons.join(', ');
// Urgent cards lead with the reason ("Gas smell"), not the job type; the type follows when it adds information.
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const what = m.urgent ? cap(reasons) + (m.problemType !== 'other' && !/no heat/.test(reasons) ? ` - ${problem}` : '') : problem;

const slack = {
  text: `${tag}: ${what} | ${addressLine} | ${m.from}`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `${tag} - ${what}`, emoji: true } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Customer*\n${m.from}` },
      { type: 'mrkdwn', text: `*Job*\n${m.jobId}` },
      { type: 'mrkdwn', text: `*Address*\n${addressLine}` },
      { type: 'mrkdwn', text: `*ZIP*\n${m.zip ?? 'not given'}` },
    ] },
    ...(m.urgent ? [{ type: 'section', text: { type: 'mrkdwn', text: `*Why urgent:* ${reasons}. Call this customer first.` } }] : []),
    { type: 'section', text: { type: 'mrkdwn', text: `> ${m.message.slice(0, 1500)}` } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `Language: ${m.language === 'es' ? 'Spanish' : 'English'} | Received ${m.receivedAt}` }] },
    { type: 'actions', block_id: `job_${m.jobId}`, elements: [
      { type: 'button', text: { type: 'plain_text', text: 'Assign' }, style: 'primary', action_id: 'assign_job', value: m.jobId },
      { type: 'button', text: { type: 'plain_text', text: 'Call back' }, ...(m.urgent ? { style: 'danger' } : {}), action_id: 'call_back', value: m.from },
    ] },
  ],
};

const sheetRow = {
  job_id: m.jobId, created_at: m.receivedAt, status: m.isUpdate ? 'Updated' : 'New', priority: m.urgent ? 'URGENT' : 'Normal',
  phone: m.from, address: m.address ? place : '', zip: m.zip ?? '', problem_type: m.problemType,
  urgency: reasons, language: m.language, message: m.message,
};
return [{ json: { ...m, slack, sheetRow } }];

// The texts back to the customer: ask for the address, or confirm the job (with safety words when it is urgent).
const cfg = $('Config').first().json;
const m = $('Dedupe & Merge').first().json;
const name = cfg.businessName;
const es = m.language === 'es';
const reasons = m.urgencyReasons;
let body;

if (m.route === 'ask_info') {
  body = es
    ? `${name}: ¡Gracias! Para enviar a un técnico necesitamos la dirección completa (calle y número) y el código postal. Por favor responda con ellos.`
    : (m.asks > 1
      ? `${name}: Sorry, we still need the street address to send a technician. Please reply with it, for example "123 Main St, Dallas TX 75201".`
      : `${name}: Thanks! To send a technician we need your street address and ZIP code. Please reply with them.`);
} else {
  const job = m.jobId;
  const safety = [];
  if (reasons.includes('gas smell') || reasons.includes('carbon monoxide')) {
    safety.push(es
      ? 'Si huele a gas o suena la alarma de monóxido de carbono, salga de la casa ahora y llame al 911 o a la línea de emergencia de la compañía de gas. No use interruptores ni teléfonos dentro.'
      : "If you smell gas or a carbon monoxide alarm is sounding, leave the building now and call 911 or your gas company's emergency line. Do not use light switches or phones inside.");
  }
  if (reasons.includes('flooding')) {
    safety.push(es ? 'Si puede hacerlo con seguridad, cierre la llave principal del agua. Si hay peligro, llame al 911.' : 'If it is safe, shut off the main water valve. If anyone is in danger, call 911.');
  }
  if (reasons.includes('smoke, fire or sparks')) {
    safety.push(es ? 'Si hay humo o fuego, saque a todos de la casa y llame al 911.' : 'If there is smoke or fire, get everyone out and call 911.');
  }
  const askAddress = m.addressMissing ? (es ? ' Por favor responda con su dirección y código postal.' : ' Please reply with your street address and ZIP code.') : '';
  let lead;
  if (m.isUpdate) lead = es ? `Gracias, recibimos la dirección (trabajo ${job}). Un técnico le llamará pronto.` : `Thanks, we got the address (job ${job}). A technician will call you back shortly.`;
  else if (m.urgent) lead = es ? `Marcamos su solicitud como URGENTE (trabajo ${job}) y estamos avisando a un técnico ahora.` : `We marked your request URGENT (job ${job}) and a technician is being alerted now.`;
  else lead = es ? `Gracias, recibimos su solicitud (trabajo ${job}). Un técnico le llamará pronto.` : `Thanks, we have your request (job ${job}). A technician will call you back shortly.`;
  body = `${name}: ${[lead + askAddress, ...safety].join(' ')}`;
}

return [{ json: { ...m, sms: { from: m.to, to: m.from, body, tag: m.route === 'ask_info' ? 'ask-address' : 'confirmation' } } }];
